// MapCreateBulk creates a bulk creation builder from the given slice. For each item in the slice, the function creates
// a builder and applies setFunc on it.
func (c *TrafficSnapshotClient) MapCreateBulk(slice any, setFunc func(*TrafficSnapshotCreate, int)) *TrafficSnapshotCreateBulk {
	rv := reflect.ValueOf(slice)
	if rv.Kind() != reflect.Slice {
		return &TrafficSnapshotCreateBulk{err: fmt.Errorf("calling to TrafficSnapshotClient.MapCreateBulk with wrong type %T, need slice", slice)}
	}
	builders := make([]*TrafficSnapshotCreate, rv.Len())
	for i := 0; i < rv.Len(); i++ {
		builders[i] = c.Create()
		setFunc(builders[i], i)
	}
	return &TrafficSnapshotCreateBulk{config: c.config, builders: builders}
}

